/// Structured parking fees v2 (docs/designs/2026-10-26-parking-conditions-and-fees.md
/// §2), shared by the app and the admin site; pure Dart so both import the
/// same rules. The JSON shape matches the `fee` column (`valid_fee()`,
/// generated by tool/gen_contract_sql.py from
/// supabase/functions/_shared/parking_contract.json) and `validFee` in
/// supabase/functions/_shared/fee.ts; [feeNoteOf] writes the sentences of
/// `fee_note_of()` and `feeNoteOf` there. parking_contract_cases.json pins
/// both for every side (test/fee_contract_test.dart).
library;

import 'dart:convert';

import 'parking_condition.dart'
    show
        feeContract,
        scheduleWeekdays,
        timeOptionalPair,
        timePattern,
        validSlotTimes;

/// How a vehicle pays. Heavy bikes may also follow another vehicle's rate.
enum FeeMode {
  /// 不適用 (#188 layer 2): no bays for this vehicle here; riders' notice
  /// boards leave it out.
  notApplicable('not_applicable'),
  free('free'),
  hourly('hourly'),
  perVisit('per_visit'),

  /// Rates that differ by time of day and day of the week (§2.2).
  byTime('by_time'),
  sameAsScooter('same_as_scooter'),
  sameAsCar('same_as_car');

  const FeeMode(this.wire);

  /// The value stored as `mode`.
  final String wire;

  /// Modes that follow another vehicle's rate, only for heavy bikes.
  bool get follows => this == sameAsScooter || this == sameAsCar;
}

/// When a daily cap or a daily charge starts over; null is unconfirmed.
enum CapReset {
  calendarDay('calendar_day'),
  rolling24h('rolling_24h'),
  perEntry('per_entry');

  const CapReset(this.wire);
  final String wire;
}

/// Whether a per-visit charge starts again after midnight (§2.5); null is
/// unconfirmed, never 不另計.
enum Renew {
  none('none'),
  midnight('midnight');

  const Renew(this.wire);
  final String wire;
}

/// How a stay crossing into another per-visit period is charged (§2.5);
/// null is unconfirmed.
enum CrossPeriod {
  eachPeriod('each_period'),
  entryOnly('entry_only');

  const CrossPeriod(this.wire);
  final String wire;
}

T? _wire<T extends Enum>(List<T> values, Object? wire, String Function(T) of) =>
    values.where((v) => of(v) == wire).firstOrNull;

int? _int(Object? v) => v is num ? v.toInt() : null;

/// One period of a by-time rate: the days (`all`, `weekday`, `holiday` or a
/// list of weekdays), [from]–[to] (both null: all day; from > to crosses
/// midnight) and its [rate], which neither follows nor nests by_time.
class FeePeriod {
  const FeePeriod({required this.days, this.from, this.to, required this.rate});
  final Object days;
  final String? from, to;
  final Rate rate;

  Map<String, Object> toJson() => {
    'days': days,
    'from': ?from,
    'to': ?to,
    'rate': rate.toJson(),
  };
}

/// Whether [json] is one vehicle's rate the column accepts (§2.2): the
/// mode's keys only, every value in range. A period's rate ([nested]) may
/// not follow or be by_time; only heavy bikes follow.
bool validRate(Object? json, String vehicle, {bool nested = false}) {
  if (json is! Map || json['mode'] is! String) return false;
  final mode = json['mode'] as String;
  final follow = feeContract['follow']! as Map<String, Object?>;
  if ((follow['modes']! as List).contains(mode)) {
    return !nested &&
        (follow['vehicles']! as List).contains(vehicle) &&
        _validFields(json, {
          'required': const <String, Object?>{},
          'optional': follow['optional'],
        }, vehicle);
  }
  final modes = feeContract['modes']! as Map<String, Object?>;
  final periods = feeContract['periods']! as Map<String, Object?>;
  if (!modes.containsKey(mode)) return false;
  if (nested && !(periods['nested_modes']! as List).contains(mode)) {
    return false;
  }
  return _validFields(json, modes[mode]! as Map<String, Object?>, vehicle);
}

bool _whole(Object? v, num min, num max) =>
    v is num && v.isFinite && v == v.truncate() && v >= min && v <= max;

bool _validFields(
  Map<Object?, Object?> json,
  Map<String, Object?> spec,
  String vehicle,
) {
  final required = spec['required']! as Map;
  final optional = spec['optional']! as Map;
  final enums = feeContract['enums']! as Map<String, Object?>;
  for (final MapEntry(:key, :value) in json.entries) {
    if (key == 'mode') continue;
    final field = required[key] ?? optional[key];
    switch (field) {
      case null:
        return false;
      case {'min': final num min, 'max': final Object max}:
        final hi = max is String ? json[max] : max;
        if (!_whole(hi, 0, 1e9) || !_whole(value, min, hi as num)) {
          return false;
        }
      case final String name when enums.containsKey(name):
        if (!(enums[name]! as List).contains(value)) return false;
      case 'periods':
        final p = feeContract['periods']! as Map<String, Object?>;
        final keys = p['keys']! as List;
        if (value is! List ||
            value.isEmpty ||
            value.length > (p['max_entries']! as int) ||
            !value.every(
              (e) =>
                  e is Map &&
                  e.keys.every(keys.contains) &&
                  keys.every(
                    (k) => e.containsKey(k) || timeOptionalPair.contains(k),
                  ) &&
                  validSlotTimes(e) &&
                  validRate(e['rate'], vehicle, nested: true),
            )) {
          return false;
        }
      default:
        return false;
    }
  }
  return required.keys.every(json.containsKey);
}

/// Whether [json] is a fee the column accepts: a rate per known vehicle,
/// within the size bound (read as UTF-8 JSON, close to the column's).
bool validFee(Object? json) =>
    json is Map &&
    utf8.encode(jsonEncode(json)).length <=
        (feeContract['max_bytes']! as int) &&
    json.entries.every(
      (e) =>
          (feeContract['vehicles']! as List).contains(e.key) &&
          validRate(e.value, e.key as String),
    );

/// Whether a valid rate is complete for a new write (#188 layer 2,
/// `fee_rate_write_complete()` in SQL): a per-visit rate names renew, an
/// hourly cap its cap_reset, and a by_time rate with two or more periods,
/// one of them per visit, its cross_period; its periods' rates the same.
bool rateWriteComplete(Object? json) {
  if (json is! Map || json['mode'] is! String) return false;
  final w = feeContract['write']! as Map<String, Object?>;
  final mode = json['mode'] as String;
  final required = (w['required']! as Map)[mode] as List? ?? const [];
  if (!required.every(json.containsKey)) return false;
  final requiredWith = (w['required_with']! as Map)[mode] as Map? ?? const {};
  for (final MapEntry(:key, :value) in requiredWith.entries) {
    if (json.containsKey(value) && !json.containsKey(key)) return false;
  }
  if (mode == 'by_time') {
    final periods = (json['periods'] as List).cast<Map<Object?, Object?>>();
    if (!periods.every((p) => rateWriteComplete(p['rate']))) return false;
    final when = w['cross_period_when']! as Map;
    if (!json.containsKey('cross_period') &&
        periods.length >= (when['min_periods'] as int) &&
        periods.any((p) => (p['rate'] as Map)['mode'] == when['nested_mode'])) {
      return false;
    }
  }
  return true;
}

/// Whether a valid fee is complete for a new write (`fee_write_complete()`):
/// every vehicle of `fee.write.required_vehicles` has a rate, each complete.
/// Official imports are exempt (PM_ANS_20261101_55).
bool feeWriteComplete(Object? json) =>
    json is Map &&
    ((feeContract['write']! as Map)['required_vehicles'] as List).every(
      json.containsKey,
    ) &&
    json.values.every(rateWriteComplete);

/// One vehicle's rate. Amounts and caps are whole yuan, periods minutes.
class Rate {
  const Rate(
    this.mode, {
    this.amount,
    this.perMinutes,
    this.dailyCap,
    this.capReset,
    this.renew,
    this.extensionAmount,
    this.periods,
    this.crossPeriod,
  });
  final FeeMode mode;
  final int? amount, perMinutes, dailyCap;
  final CapReset? capReset;
  final Renew? renew;

  /// Per visit: what each extension costs (延長每次多少錢, #188 layer 2);
  /// how long and how many times is the condition's time limit.
  final int? extensionAmount;
  final List<FeePeriod>? periods;
  final CrossPeriod? crossPeriod;

  /// The rate in [json], or null when it is not one the column accepts:
  /// an unknown mode or key, or any value out of range, optional or not.
  static Rate? fromJson(Object? json, {required bool heavy}) =>
      validRate(json, heavy ? 'heavy' : 'scooter')
      ? _build(json! as Map)
      : null;

  static Rate _build(Map<Object?, Object?> json) {
    final mode = _wire(FeeMode.values, json['mode'], (m) => m.wire)!;
    final periods = json['periods'];
    return Rate(
      mode,
      amount: _int(json['amount']),
      perMinutes: _int(json['per_minutes']),
      dailyCap: _int(json['daily_cap']),
      capReset: _wire(CapReset.values, json['cap_reset'], (v) => v.wire),
      renew: _wire(Renew.values, json['renew'], (v) => v.wire),
      extensionAmount: _int(json['extension_amount']),
      periods: periods is List
          ? [
              for (final p in periods.cast<Map<Object?, Object?>>())
                FeePeriod(
                  days: p['days'] is List
                      ? List<String>.from(p['days'] as List)
                      : p['days'] as String,
                  from: p['from'] as String?,
                  to: p['to'] as String?,
                  rate: _build(p['rate'] as Map),
                ),
            ]
          : null,
      crossPeriod: _wire(
        CrossPeriod.values,
        json['cross_period'],
        (v) => v.wire,
      ),
    );
  }

  /// Whether the mode has every value it needs to be shown or stored.
  bool get complete => switch (mode) {
    FeeMode.hourly => amount != null && perMinutes != null,
    FeeMode.perVisit => amount != null,
    FeeMode.byTime => periods?.isNotEmpty ?? false,
    _ => true,
  };

  /// Whether a new write may store it (#188 layer 2, [rateWriteComplete]).
  bool get writeComplete => complete && rateWriteComplete(toJson());

  /// Only the keys this mode uses, as the column requires.
  Map<String, Object> toJson() => {
    'mode': mode.wire,
    if (mode == FeeMode.hourly) ...{
      'amount': ?amount,
      'per_minutes': ?perMinutes,
      'daily_cap': ?dailyCap,
      'cap_reset': ?capReset?.wire,
    },
    if (mode == FeeMode.perVisit) ...{
      'amount': ?amount,
      'renew': ?renew?.wire,
      'extension_amount': ?extensionAmount,
    },
    if (mode == FeeMode.byTime) ...{
      'periods': ?periods?.map((p) => p.toJson()).toList(),
      'cross_period': ?crossPeriod?.wire,
    },
  };

  /// The rate as riders read it, e.g. 每小時 20 元，當日上限 100 元（零時重算）.
  /// A follow names what it follows (an editor label); [Fee.textOf] and
  /// [feeNoteOf] show the amounts worked out instead.
  String get text => switch (mode) {
    FeeMode.notApplicable => '不適用',
    FeeMode.sameAsScooter => '比照機車費率',
    FeeMode.sameAsCar => '比照汽車費率',
    _ => _rateText(toJson(), 100) ?? '',
  };

  @override
  bool operator ==(Object other) =>
      other is Rate && jsonEncode(other.toJson()) == jsonEncode(toJson());

  @override
  int get hashCode => jsonEncode(toJson()).hashCode;
}

/// A rate per vehicle; a null vehicle is unconfirmed.
class Fee {
  const Fee({this.scooter, this.heavy, this.car});
  final Rate? scooter, heavy, car;

  /// The fee in [json]; vehicles whose rate is not valid read as
  /// unconfirmed (an old cached `daily` or `posted` too, #188 layer 2).
  static Fee fromJson(Object? json) => json is Map
      ? Fee(
          scooter: Rate.fromJson(json['scooter'], heavy: false),
          heavy: Rate.fromJson(json['heavy'], heavy: true),
          car: Rate.fromJson(json['car'], heavy: false),
        )
      : const Fee();

  /// The fee in [json] when all of it is one the column accepts, else null.
  /// Unlike [fromJson], an unknown vehicle or a bad rate is not dropped
  /// silently, so a value from elsewhere (a report) is taken whole or not
  /// at all.
  static Fee? tryParse(Object? json) =>
      json is Map && validFee(json) ? fromJson(json) : null;

  bool get isEmpty => scooter == null && heavy == null && car == null;

  /// Whether every rate given has its amounts, in the column's ranges.
  bool get valid => validFee(toJson());

  /// Whether a rider's or an admin's new write may store it (#188 layer 2):
  /// valid, every vehicle given, each rate complete ([feeWriteComplete]).
  bool get writeComplete => valid && feeWriteComplete(toJson());

  Map<String, Object> toJson() => {
    if (scooter case final rate?) 'scooter': rate.toJson(),
    if (heavy case final rate?) 'heavy': rate.toJson(),
    if (car case final rate?) 'car': rate.toJson(),
  };

  /// This fee with the given vehicles replaced; the others stay as they are.
  Fee copyWith({
    Rate? Function()? scooter,
    Rate? Function()? heavy,
    Rate? Function()? car,
  }) => Fee(
    scooter: scooter == null ? this.scooter : scooter(),
    heavy: heavy == null ? this.heavy : heavy(),
    car: car == null ? this.car : car(),
  );

  /// One vehicle's rate as riders read it, a heavy follow with its amounts
  /// worked out (#140); null when unconfirmed, including a follow of an
  /// unconfirmed vehicle.
  String? textOf(String vehicle) {
    final json = toJson();
    if (vehicle == 'heavy') return _heavyText(json).text;
    return _rateText(json[vehicle], 100);
  }

  /// One vehicle's rate for a rider's screen: [textOf], or 費率未提供 when a
  /// heavy rate follows a vehicle whose rate is unconfirmed; null when the
  /// vehicle's rate is unconfirmed.
  String? riderText(String vehicle) =>
      textOf(vehicle) ??
      (vehicle == 'heavy' && (heavy?.mode.follows ?? false) ? '費率未提供' : null);

  /// One line for every vehicle, as stored in `fee_note`; empty when no
  /// vehicle is known.
  String get summary => isEmpty ? '' : feeNoteOf(this);

  /// Why a heavy follow cannot be stored (design §8.6, #155 item 13): the
  /// vehicle it follows has no known rate, so riders would read 費率未提供.
  /// Null when the heavy rate follows nothing or its source is known. Shared
  /// by the FeeEditor and every form that saves a fee without one (the admin
  /// spot form, the review page).
  String? get followGap {
    final mode = heavy?.mode;
    if (mode == null || !mode.follows) return null;
    final car = mode == FeeMode.sameAsCar;
    final source = car ? this.car : scooter;
    final wire = car ? 'car' : 'scooter';
    if (source != null &&
        source.mode != FeeMode.notApplicable &&
        validRate(source.toJson(), wire) &&
        _rateText(toJson()[wire], 100) != null) {
      return null;
    }
    final name = car ? '汽車' : '機車';
    return '大型重機比照$name費率，但還沒填$name費率。請填$name費率，或改選其他收費方式。';
  }

  @override
  bool operator ==(Object other) =>
      other is Fee &&
      other.scooter == scooter &&
      other.heavy == heavy &&
      other.car == car;

  @override
  int get hashCode => Object.hash(scooter, heavy, car);
}

/// A spot's stored `fee` as a [Fee], or null when it holds no structured
/// data: not an object, or `{}` (#114, as fee_note_matches() reads it).
/// Without one, riders read `fee_note`.
Fee? structuredFee(Object? json) =>
    json is Map && json.isNotEmpty ? Fee.fromJson(json) : null;

/// The fee a suggestion leaves (design §5.4, §7 item 3): [current] with
/// each vehicle [proposed] names replaced, or removed where it is null.
/// Vehicles it leaves out keep their rates, so an older build that cannot
/// read a vehicle never clears it by omission.
Map<String, Object?> mergeFeeJson(Object? current, Object? proposed) {
  final out = <String, Object?>{
    if (current is Map)
      for (final MapEntry(:key, :value) in current.entries) '$key': value,
  };
  if (proposed is Map) {
    for (final MapEntry(:key, :value) in proposed.entries) {
      if (value == null) {
        out.remove('$key');
      } else {
        out['$key'] = value;
      }
    }
  }
  return out;
}

/// A fee suggestion (`proposed.fee`) turning [current] into [edited]: the
/// edited rates, plus null for each vehicle [current] has that [edited]
/// cleared. A vehicle [current] lacks — unconfirmed, or one this build
/// cannot read — is left out, so the suggestion never clears it.
Map<String, Object?> feeSuggestion(Fee? current, Fee edited) {
  final before = current?.toJson() ?? const <String, Object>{};
  final after = edited.toJson();
  return {
    ...after,
    for (final vehicle in before.keys)
      if (!after.containsKey(vehicle)) vehicle: null,
  };
}

/// The `fee_note` text stored beside [fee] (§2.5): the known vehicles as
/// 機車…；大型重機…；汽車…, then 大型重機費率未提供 when the heavy rate is
/// unknown (PM_ANS_20261101_55); a vehicle that is not_applicable is left
/// out; the default note when no vehicle is known.
String feeNoteOf(Fee? fee) => feeNoteOfJson(fee?.toJson());

/// [feeNoteOf] of a fee as JSON, as `fee_note_of()` takes it.
String feeNoteOfJson(Object? fee) {
  final f = fee is Map ? fee : const <Object?, Object?>{};
  final s = _rateText(f['scooter'], 100), c = _rateText(f['car'], 100);
  final (:text, :unprovided) = _heavyText(f);
  if (s == null && text == null && c == null && !unprovided) {
    return defaultFeeNote;
  }
  return [
    if (s != null) '機車$s',
    if (text != null || unprovided) '大型重機${text ?? '費率未提供'}',
    if (c != null) '汽車$c',
    if (text == null &&
        !unprovided &&
        (f['heavy'] as Map?)?['mode'] != FeeMode.notApplicable.wire)
      '大型重機費率未提供',
  ].join('；');
}

/// The note of a spot without a known fee.
const defaultFeeNote = '請依現場公告';

/// The longest [feeNoteOf] the contract allows (§2.5), as
/// supabase/functions/_shared/fee_note_limit.json holds it; the spot
/// tables' fee_note check. Free text stays within [freeFeeNoteMaxLength].
const feeNoteMaxLength = 1399;
const freeFeeNoteMaxLength = 200;

/// Whether [note] fits as a spot's fee_note beside [fee], as the tables'
/// check: free text up to 200, or exactly the fee's sentence, which may be
/// longer (up to [feeNoteMaxLength]).
bool feeNoteFits(Object? note, Fee? fee) =>
    note is String &&
    (note.length <= freeFeeNoteMaxLength ||
        (fee != null &&
            note.length <= feeNoteMaxLength &&
            note == feeNoteOf(fee)));

({String? text, bool unprovided}) _heavyText(Map<Object?, Object?> f) {
  final heavy = f['heavy'];
  if (heavy is Map &&
      (heavy['mode'] == 'same_as_scooter' || heavy['mode'] == 'same_as_car')) {
    final target = heavy['mode'] == 'same_as_scooter' ? f['scooter'] : f['car'];
    final text = _rateText(target, 100);
    return (text: text, unprovided: text == null);
  }
  return (text: _rateText(heavy, 100), unprovided: false);
}

const _resets = {
  'calendar_day': '零時重算',
  'rolling_24h': '停滿 24 小時重算',
  'per_entry': '每次進場重算',
};
const _dayMasks = {'all': 127, 'weekday': 31, 'holiday': 96};
const _dayNames = '一二三四五六日';

/// Whole yuan at [pct] percent, with at most two decimals: 22.5, 41.25.
/// An incomplete rate (an editor's draft) reads its missing amount as 0.
String _money(Object? amount, int pct) {
  final v = (_int(amount) ?? 0) * pct, whole = v ~/ 100, rem = v % 100;
  if (rem == 0) return '$whole';
  if (rem % 10 == 0) return '$whole.${rem ~/ 10}';
  return '$whole.${rem.toString().padLeft(2, '0')}';
}

String _span(Object? v) {
  final m = _int(v)!;
  return m % 60 == 0 ? '${m ~/ 60} 小時' : '$m 分鐘';
}

String _every(Object? v) {
  final m = _int(v) ?? 60;
  return m == 60
      ? '每小時'
      : m % 60 == 0
      ? '每 ${m ~/ 60} 小時'
      : '每 $m 分鐘';
}

int _dayMask(Object? days) => days is String
    ? _dayMasks[days]!
    : (days! as List).fold(
        0,
        (m, d) => m | (1 << scheduleWeekdays.indexOf(d as String)),
      );

String _dayLabel(int mask) => switch (mask) {
  127 => '每天',
  31 => '平日',
  96 => '假日',
  _ => [
    for (var i = 0; i < 7; i++)
      if (mask & (1 << i) != 0) '週${_dayNames[i]}',
  ].join('、'),
};

/// One rate's words at [pct] percent, or null when it reads as unconfirmed
/// or does not apply (not_applicable, or a follow out of place).
String? _rateText(Object? r, int pct) {
  if (r is! Map) return null;
  switch (r['mode']) {
    case 'free':
      return '免費';
    case 'hourly':
      var t = '${_every(r['per_minutes'])} ${_money(r['amount'], pct)} 元';
      if (r.containsKey('daily_cap')) {
        t += '，當日上限 ${_money(r['daily_cap'], pct)} 元';
        if (_resets[r['cap_reset']] case final reset?) t += '（$reset）';
      }
      return t;
    case 'per_visit':
      var t = '每次 ${_money(r['amount'], pct)} 元';
      if (r['renew'] == 'midnight') t += '，隔日另計';
      if (r['renew'] == 'none') t += '，停多久都只收一次';
      if (r.containsKey('extension_amount')) {
        t += '，延長每次 ${_money(r['extension_amount'], pct)} 元';
      }
      return t;
    case 'by_time':
      // Periods grouped by the days they cover, in order of first appearance.
      final groups = <int, List<String>>{};
      for (final p in (r['periods'] as List).cast<Map<Object?, Object?>>()) {
        final text = _rateText(p['rate'], pct);
        if (text == null) continue;
        final from = p['from'] as String?, to = p['to'] as String?;
        final time = from == null
            ? '全天'
            : '$from–${from.compareTo(to!) < 0 ? '' : '隔日 '}$to';
        groups.putIfAbsent(_dayMask(p['days']), () => []).add('$time $text');
      }
      if (groups.isEmpty) return null;
      var t = [
        for (final MapEntry(:key, :value) in groups.entries)
          '${_dayLabel(key)}：${value.join('；')}',
      ].join('；');
      if (r.containsKey('cross_period')) {
        t += r['cross_period'] == 'each_period' ? '；跨時段分別計費' : '；依進場時段計費';
      }
      return t;
  }
  return null;
}

/// Minutes in a week, Monday 00:00 first: how [feeWeekCoverage] counts.
const weekMinutes = 7 * 1440;

int? _clockOf(Object? hhmm) {
  if (hhmm is! String || !RegExp(timePattern).hasMatch(hhmm)) return null;
  return int.parse(hhmm.substring(0, 2)) * 60 + int.parse(hhmm.substring(3));
}

/// The minutes of the week, as `[start, end)` ranges (Monday 00:00 is 0),
/// that the time-of-day period on [days] from [from] to [to] covers; a
/// Sunday night's ends past [weekMinutes], in the next week's Monday.
/// Decision 47: a period across midnight belongs to the day it starts, so
/// 平日 20:00–08:00 runs from Friday 20:00 to Saturday 08:00, and not from
/// Monday 00:00. A period without times covers its days whole; one with
/// invalid times (an editor's draft) covers nothing.
List<(int, int)> feePeriodSpans(Object? days, String? from, String? to) {
  if (days == null) return const [];
  final mask = _dayMask(days);
  final allDay = from == null && to == null;
  final start = _clockOf(from), end = _clockOf(to);
  if (!allDay && (start == null || end == null || start == end)) {
    return const [];
  }
  return [
    for (var d = 0; d < 7; d++)
      if (mask & (1 << d) != 0)
        if (allDay)
          (d * 1440, d * 1440 + 1440)
        else if (start! < end!)
          (d * 1440 + start, d * 1440 + end)
        else
          (d * 1440 + start, d * 1440 + 1440 + end),
  ];
}

/// Which minutes of the week the periods cover, as [feePeriodSpans] reads
/// each one (decision 47).
List<bool> feeWeekCoverage(
  Iterable<({Object? days, String? from, String? to})> periods,
) {
  final covered = List.filled(weekMinutes, false);
  for (final p in periods) {
    for (final (start, end) in feePeriodSpans(p.days, p.from, p.to)) {
      covered.fillRange(start, end.clamp(0, weekMinutes), true);
      if (end > weekMinutes) covered.fillRange(0, end - weekMinutes, true);
    }
  }
  return covered;
}

/// Pieces of the [feeNoteOf] sentences, so the notice board
/// (lib/ui/fee_board.dart) lays a rate out line by line in the same words.
abstract final class FeeWords {
  /// Whole yuan at [pct] percent: 22.5, 41.25.
  static String money(int? amount, [int pct = 100]) => _money(amount, pct);

  /// 20 分鐘, 3 小時.
  static String span(int minutes) => _span(minutes);

  /// 每小時, 每 30 分鐘.
  static String every(int? minutes) => _every(minutes);

  /// 零時重算 and the like; null when unconfirmed.
  static String? reset(CapReset? reset) => _resets[reset?.wire];

  /// A period's `days` as a bit per weekday, Monday first.
  static int dayMask(Object days) => _dayMask(days);

  /// 每天, 平日, 假日 or the weekdays: 週六, 週一、週三.
  static String dayLabel(int mask) => _dayLabel(mask);
}
